import {installOfflineNetworkBoundary} from './offline-network-boundary.js';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {test,expect,type Page} from '@playwright/test';
test.beforeAll(async({browser,browserName})=>{fs.mkdirSync('reports',{recursive:true});fs.writeFileSync('reports/productivity-browser-runtime-'+browserName+'.json',JSON.stringify({browserName,browserVersion:browser.version(),executableSha256:createHash('sha256').update(fs.readFileSync(browser.browserType().executablePath())).digest('hex'),nodeVersion:process.version,platform:process.platform,architecture:process.arch}));});
const password='synthetic-browser-password';
async function login(page:Page,role:string,canonical=true){await page.goto('/');await page.getByPlaceholder('Nhập tên đăng nhập gia đình...').fill('browser-'+role);await page.getByPlaceholder('Mật khẩu của từng thành viên...').fill(password);await page.getByRole('button',{name:'Đăng nhập Gia Đình',exact:true}).click();await expect(page.getByRole('button',{name:'Mở hồ sơ của Synthetic '+role,exact:true})).toBeVisible();await page.locator('aside nav').getByRole('button',{name:'Nhóm Task',exact:true}).click();if(canonical)await expect(page.getByRole('button',{name:'Danh sách',exact:true})).toBeVisible();}
const browserErrors=new WeakMap<Page,string[]>(),networkErrors=new WeakMap<Page,string[]>();
test.beforeEach(async({context,page,baseURL})=>{if(!baseURL)throw Error('Owned production server URL is required');const errors:string[]=[],external:string[]=[];networkErrors.set(page,external);browserErrors.set(page,errors);page.on('pageerror',error=>errors.push(error.message));await installOfflineNetworkBoundary(context,baseURL,external);await context.addInitScript(()=>localStorage.setItem('family_lang','vi'));});
test.afterEach(async({page})=>{await page.evaluate(()=>{(window as any).__p04FetchGate?.restore();(window as any).__p05SearchFaultRestore?.();(window as any).__p10SeriesDeniedRestore?.();});expect(browserErrors.get(page)??[],'uncaught browser errors').toEqual([]);expect(networkErrors.get(page)??[],'unexpected browser network destination').toEqual([]);});
test('P04 C01 shared drawer keeps no-date/none and dirty draft across close and view changes',async({page,browserName})=>{
 await login(page,'admin');await page.locator('[data-task-id="ui-root-'+browserName+'"]').click();const drawer=page.getByRole('dialog',{name:'Chi tiết công việc',exact:true});await expect(drawer).toBeVisible();await expect(drawer.getByRole('button',{name:'Ưu tiên',exact:true})).toContainText('Không ưu tiên');await expect(drawer.getByRole('textbox',{name:'Hạn theo ngày',exact:true})).toHaveValue('');await drawer.getByRole('textbox',{name:'Tên công việc',exact:true}).fill('Synthetic draft '+browserName);await drawer.getByRole('button',{name:'Đóng',exact:true}).click();await page.getByRole('button',{name:'Đóng và giữ bản nháp',exact:true}).click();await expect(drawer).toHaveCount(0);await page.getByRole('button',{name:'Kanban hiện có',exact:true}).click();await page.getByRole('button',{name:'Danh sách',exact:true}).click();await page.locator('[data-task-id="ui-root-'+browserName+'"]').click();await expect(drawer.getByRole('textbox',{name:'Tên công việc',exact:true})).toHaveValue('Synthetic draft '+browserName);await drawer.getByRole('button',{name:'Lưu',exact:true}).click();await expect(drawer.getByRole('textbox',{name:'Tên công việc',exact:true})).toHaveValue('Synthetic draft '+browserName);await expect(drawer.getByRole('button',{name:'Ưu tiên',exact:true})).toContainText('Không ưu tiên');await expect(drawer.getByRole('textbox',{name:'Hạn theo ngày',exact:true})).toHaveValue('');
});
