test('P04 C09 inactive bootstrap keeps legacy workspace without canonical requests',async({page})=>{
 await page.addInitScript(()=>{const original=window.fetch;(window as any).__canonicalRequests=[];(window as any).__capabilityReplies=0;window.fetch=async(input,init)=>{const url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url,location.origin);if(url.pathname==='/api/productivity/tasks')(window as any).__canonicalRequests.push(url.pathname);const response=await original.call(window,input,init);if(url.pathname==='/api/version'&&response.ok){const value=await response.json();(window as any).__capabilityReplies++;return new Response(JSON.stringify({...value,productivityActive:false}),{status:response.status,headers:response.headers});}return response;};});
 await login(page,'admin',false);await expect.poll(()=>page.evaluate(()=>(window as any).__capabilityReplies)).toBeGreaterThan(0);await expect(page.locator('#task-filter-panel')).toBeVisible();await expect(page.getByRole('button',{name:'Danh sách',exact:true})).toHaveCount(0);expect(await page.evaluate(()=>(window as any).__canonicalRequests)).toEqual([]);
});
