 const remote=await page.evaluate(async title=>{const headers={Authorization:'Bearer '+localStorage.getItem('family_token'),'Content-Type':'application/json'},rows=await(await fetch('/api/productivity/views',{headers})).json(),view=rows.views.find((row:any)=>row.title===title),input={id:view.id,title:'Remote '+title,filter:view.filter,kind:view.kind,config:view.config},response=await fetch('/api/productivity/views',{method:'POST',headers:{...headers,'x-request-id':crypto.randomUUID()},body:JSON.stringify({expectedRevision:view.revision,input})});return {status:response.status,view:(await response.json()).view};},'Synthetic saved P05 '+browserName);expect(remote.status).toBe(200);
 await page.getByRole('button',{name:'Góc nhìn đã lưu',exact:true}).click();await expect(page.getByRole('option',{name:remote.view.title,exact:true})).toBeVisible();await page.keyboard.press('Escape');await expect(page.getByRole('textbox',{name:'Tên góc nhìn đã lưu',exact:true})).toHaveValue('Synthetic saved P05 '+browserName);
