 const unsupported=await page.evaluate(async view=>{const headers={Authorization:'Bearer '+localStorage.getItem('family_token'),'Content-Type':'application/json'},response=await fetch('/api/productivity/views',{method:'POST',headers:{...headers,'x-request-id':crypto.randomUUID()},body:JSON.stringify({expectedRevision:view.revision,input:{id:view.id,title:'Unsupported '+view.title,filter:view.filter,kind:'list',config:{kind:'list',sort:'due',group:'assignee'}}})});return {status:response.status,view:(await response.json()).view};},remote.view);expect(unsupported.status).toBe(200);await page.getByRole('button',{name:'Góc nhìn đã lưu',exact:true}).click();await page.getByRole('option',{name:unsupported.view.title,exact:true}).click();await expect(page.getByRole('alert')).toContainText('Cấu hình đã lưu được giữ nguyên');
