le('button',{name:'Tìm kiếm toàn cục',exact:true}).click();const search=page.getByRole('dialog',{name:'Tìm kiếm toàn cục',exact:true});await search.getByPlaceholder('Tìm công việc, ghi chú, thu chi, giấy tờ...').fill('dua don tre '+browserName);await expect.poll(()=>page.evaluate(()=>(window as any).__p05SearchFaultCount)).toBe(1);await expect(search.getByRole('alert')).toHaveText('Không tìm kiếm được. Vui lòng thử lại.');await search.getByRole('button',{name:'Thử lại',exact:true}).click();const result=search.getByRole('button').filter({has:page.getByText('Đưa đón trẻ '+browserName,{exact:true})});await expect(result).toHaveCount(1);expect(await page.evaluate(()=>(window as any).__p05CacheMiss)).toBe(1);expect(await page.evaluate(()=>(window as any).__p05CacheRefreshReplies)).toEqual([]);await page.evaluate(()=>(window as any).__p05AllowCacheRefresh=true);await result.click();await expect.poll(()=>page.evaluate(()=>(window as any).__p05CacheRefreshReplies.length)).toBe(1);const refreshed=await page.evaluate(()=>(window as any).__p05CacheRefreshReplies[0]);expect(refreshed.status).toBe(200);expect(refreshed).toEqual({status:200,method:'GET',authorized:true,cache:'no-store'});const drawer=page.getByRole('dialog',{name:'Chi tiết công việc',exact:true});await expect(drawer).toBeVisible();await expect(drawer.getByRole('textbox',{name:'Tên công việc',exact:true})).toHaveValue('Đưa đón trẻ '+browserName);await expect(page.locator('[data-task-id="ui-query-'+browserName+'"]').first()).toBeVisible();
