async function matrixRequest(page:Page,route:string,method='GET',body?:unknown){return page.evaluate(async packet=>{const response=await fetch('/api/productivity'+packet.route,{method:packet.method,headers:{Authorization:'Bearer '+localStorage.getItem('family_token'),'Content-Type':'application/json','x-request-id':crypto.randomUUID()},...(packet.body===undefined?{}:{body:JSON.stringify(packet.body)})});return {status:response.status,body:await response.json()};},{route,method,body});}
async function matrixSeed(page:Page,title:string,preset='priority_only',priorities=['high']){const tasks=[];for(const [index,priority]of priorities.entries()){const response=await matrixRequest(page,'/tasks','POST',{expectedRevision:0,input:{listId:'legacy-family',title:title+' '+index,priority,due:{kind:'none'}}});expect(response.status).toBe(200);tasks.push(response.body.task);}const view=await matrixRequest(page,'/views','POST',{expectedRevision:0,input:{title,filter:{rootsOnly:true,query:title},kind:'matrix',config:{kind:'matrix',preset,horizonDays:1,rules:null,order:['q1','q2','q3','q4'],showCompleted:false}}});expect(view.status).toBe(200);return {tasks,view:view.body.view};}
async function matrixChoose(page:Page,title:string){await page.getByRole('button',{name:'Matrix',exact:true}).click();await page.getByRole('button',{name:'Matrix đã lưu',exact:true}).click();await page.getByRole('option',{name:title,exact:true}).click();await expect(page.getByRole('region',{name:'Ma trận công việc',exact:true})).toBeVisible();}
async function matrixMoveMenu(page:Page,id:string,target:string,keyboard=false){const card=page.locator('[data-matrix-task="'+id+'"]');if(await card.locator('details').getAttribute('open')===null)await card.getByText('Chuyển tới',{exact:true}).click();const button=card.getByRole('button',{name:new RegExp('^'+target+'(?: ·|$)')});if(keyboard){await button.focus();await page.keyboard.press('Enter');}else await button.click();const modal=page.getByRole('dialog',{name:'Xem trước di chuyển',exact:true});await expect(modal).toBeVisible();return {card,button,modal};}
