async function holdSectionPreview(page:Page){await page.evaluate(()=>{const original=window.fetch;let release!:()=>void;const held=new Promise<void>(resolve=>release=resolve),requests:any[]=[];const wrapped:typeof fetch=async(input,init)=>{const url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url,location.origin),response=await original.call(window,input,init);if(url.origin===location.origin&&url.pathname==='/api/productivity/boards/preview'&&init?.method==='POST'&&requests.length===0){requests.push({path:url.pathname,method:init.method,status:response.status,signal:!!init.signal});await held;}return response;};window.fetch=wrapped;(window as any).__p04FetchGate={requests,release,restore:()=>{release();if(window.fetch===wrapped)window.fetch=original;delete (window as any).__p04FetchGate;}};});return {arrived:async()=>{await expect.poll(()=>page.evaluate(()=>(window as any).__p04FetchGate.requests.length)).toBe(1);expect(await page.evaluate(()=>(window as any).__p04FetchGate.requests)).toEqual([{path:'/api/productivity/boards/preview',method:'POST',status:200,signal:true}]);},release:()=>page.evaluate(()=>(window as any).__p04FetchGate.release())};}
