// Observe the application's original native JSON read without asking Chromium's
// CDP cache for a body or leaving a cloned stream past owner invalidation.
// The original fetch/Response/input/init/signal are preserved. No second request,
// response fulfillment, delay, retry, navigation or provider replacement occurs.
async function applyGroup(page:Page,dialog:ReturnType<Page['getByRole']>,afterPreview?:()=>Promise<void>){
 await dialog.getByRole('button',{name:'Xem trước đổi nhóm',exact:true}).click();await expect(dialog.getByTestId('kanban-group-apply')).toBeEnabled();if(afterPreview)await afterPreview();
 await page.evaluate(()=>{
  if((window as any).__p09GroupApply)throw Error('Native apply observer already installed');
  const original=window.fetch,requests:any[]=[];let complete!:(packet:any)=>void;
  const result=new Promise<any>(resolve=>complete=resolve);
  const wrapped:typeof fetch=async(input,init)=>{
   const request=input instanceof Request?input:null,url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url,location.origin),method=init?.method??request?.method??'GET';
   const observed=url.origin===location.origin&&url.pathname==='/api/productivity/boards/grouped/apply'&&method==='POST',headers=new Headers(init?.headers??request?.headers);
   let body:unknown=null;if(observed)try{body=JSON.parse(String(init?.body));}catch{}
   const metadata=observed?{path:url.pathname,method,authorized:headers.has('Authorization'),requestId:headers.get('x-request-id'),cache:init?.cache??request?.cache,signal:!!(init?.signal??request?.signal),input:body}:null;
   if(metadata)requests.push(metadata);
   const response=await original.call(window,input,init);
   if(metadata)try{
    const readJSON=response.json.bind(response);let reads=0;
    response.json=async()=>{reads++;try{const body=await readJSON();complete({metadata,status:response.status,body:structuredClone(body),reads});return body;}catch(error){complete({metadata,status:response.status,error:String(error),reads});throw error;}};
   }catch(error){complete({metadata,status:response.status,error:String(error)});}
   return response;
  };
  window.fetch=wrapped;(window as any).__p09GroupApply={result,requests,restore:()=>{if(window.fetch===wrapped)window.fetch=original;delete (window as any).__p09GroupApply;}};
 });
 try{
  const received=page.waitForResponse(response=>response.url().endsWith('/api/productivity/boards/grouped/apply')&&response.request().method()==='POST'),captured=page.evaluate(()=>(window as any).__p09GroupApply.result);
  const [response,packet]=await Promise.all([received,captured,dialog.getByTestId('kanban-group-apply').click()]);
  if(packet.error)await test.info().attach('native-apply-abort-evidence',{body:JSON.stringify(packet),contentType:'application/json'});expect(response.status()).toBe(200);expect(packet.status).toBe(200);expect(packet.error).toBeUndefined();expect(packet.reads).toBe(1);
  expect(packet.metadata).toMatchObject({path:'/api/productivity/boards/grouped/apply',method:'POST',authorized:true,cache:'no-store',signal:true});expect(packet.metadata.requestId).toMatch(/^[a-f0-9-]{36}$/);expect(response.request().headers()['x-request-id']).toBe(packet.metadata.requestId);
  expect(packet.body.task.id).toBe(packet.metadata.input.input.taskId);expect(typeof packet.body.taskChanged).toBe('boolean');expect(packet.body.task.revision).toBe(packet.metadata.input.expectedRevision+(packet.body.taskChanged?1:0));await expect(dialog).toHaveCount(0);expect(await page.evaluate(()=>(window as any).__p09GroupApply.requests.length)).toBe(1);return packet.body;
 }finally{await page.evaluate(()=>(window as any).__p09GroupApply?.restore());}
}
