 // Intercept at the app fetch boundary: Windows WebKit registered page.route
 // but sent this POST to the real server. A real Response preserves parsing,
 // status handling and the caller's complete command envelope on every engine.
 await page.evaluate(path=>{const original=window.fetch,calls:{path:string;method:string;authorized:boolean;cache:string|undefined;requestId:string|null;body:unknown;status:number;reads:number}[]=[];const wrapped:typeof fetch=async(input,init)=>{const url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url,location.origin),method=init?.method??(input instanceof Request?input.method:'GET');if(url.origin===location.origin&&url.pathname===path&&method==='POST'){const headers=new Headers(init?.headers??(input instanceof Request?input.headers:undefined)),call={path:url.pathname,method,authorized:headers.has('Authorization'),cache:init?.cache,requestId:headers.get('x-request-id'),body:JSON.parse(String(init?.body)),status:403,reads:0};calls.push(call);const response=new Response(JSON.stringify({error:'Synthetic series authority revoked'}),{status:403,headers:{'content-type':'application/json'}}),read=response.json.bind(response);response.json=()=>{call.reads++;return read();};return response;}return original.call(window,input,init);};window.fetch=wrapped;(window as any).__p10SeriesDeniedCalls=calls;(window as any).__p10SeriesDeniedRestore=()=>{if(window.fetch===wrapped)window.fetch=original;delete (window as any).__p10SeriesDeniedRestore;};},path);
