// Created after C01–C30 through retained authenticated app routes; no seeded
// extra family can alter the earlier Matrix/Kanban inventories or WIP counts.
async function legacyFamilyForCutover(page:Page,label:string,pending=false){
 return page.evaluate(async({label,pending,password})=>{const admin=localStorage.getItem('family_token')!;const call=async(path:string,body?:unknown,token=admin)=>{const response=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json','x-request-id':crypto.randomUUID()},...(body===undefined?{}:{body:JSON.stringify(body)})});const result=await response.json();if(response.status!==200)throw Error(path+' '+response.status+' '+JSON.stringify(result));return result;};const root=(await call('/tasks',{title:'Synthetic cutover root '+label,isShared:true,assigneeId:'browser-child',recurrenceType:'monthly',dueDate:'2027-01-31',rewardPoints:0})).task;await call('/tasks',{id:root.id,status:'completed'});const descendants=(await call('/tasks')).tasks.filter((task:any)=>task.sourceRecurringTaskId===root.id);if(descendants.length!==1)throw Error('Synthetic legacy generator must produce exactly one child');const child=descendants[0];await call('/tasks',{id:child.id,title:'Synthetic cutover selected '+label,assigneeId:'browser-child',rewardPoints:35});const canonical=(await call('/productivity/tasks/'+root.id)).task;await call('/productivity/tasks/'+root.id+'/reopen',{expectedRevision:canonical.revision});if(pending){const login=await call('/auth/login',{username:'browser-child',password});await call('/tasks',{id:child.id,status:'completed',proofNote:'Synthetic cutover pending proof '+label},login.token);}return {rootId:root.id,id:child.id};},{label,pending,password});
}
