dy={expectedRevision:current.revision},approvalPair=await page.evaluate(async({id,body})=>{const key=crypto.randomUUID(),headers={Authorization:'Bearer '+localStorage.getItem('family_token'),'Content-Type':'application/json','x-request-id':key},send=async()=>{const response=await fetch('/api/productivity/tasks/'+id+'/approve',{method:'POST',headers,body:JSON.stringify(body)});return {status:response.status,body:await response.json()};};return {first:await send(),replay:await send()};},{id:family.id,body}),accepted=approvalPair.first;expect(approvalPair.replay).toEqual(accepted);expect(accepted.status).toBe(200);expect(accepted.body.spawnedTaskIds).toHaveLength(1);const next=(await matrixRequest(page,'/tasks/'+accepted.body.spawnedTaskIds[0])).body.task;expect(next).toMatchObject({assigneeId:'browser-member',due:{kind:'all_day',date:'2027-03-28',timezone:'Asia/Saigon'}});expect((await matrixRequest(page,'/tasks/'+family.id+'/series')).body.series).toMatchObject({acceptedCount:1,rotationCursor:1});const repeated=await matrixRequest(page,'/tasks/'+family.id+'/approve','POST',{expectedRevision:accepted.body.task.revision});expect(repeated.status).toBe(200);expect(repeated.body.spawnedTaskIds).toEqual([]);expect(repeated.body.task).toEqual(accepted.body.task);expect((await matrixRequest(page,'/tasks/'+family.id+'/series')).body.series).toMatchObject({acceptedCount:1,rotationCursor:1});const rewardsAccepted=await page.evaluate(async()=>{const response=await fetch('/api/rewards',{headers:{Authorization:'Bearer '+localStorage.getItem('family_token')}});if(response.status!==200)throw Error('Synthetic reward read');return response.json();});expect(rewardsAccepted.entries.filter((row:any)=>row.taskId===family.id)).toEqual([expect.objectContaining({points:35,userId:'browser-child'})]);expect(rewardsAccepted.entries.filter((row:any)=>row.taskId!==family.id)).toEqual(rewardsBefore.entries);await drawer.getByRole('button',{name:'Đóng',exact:true}).click();
